    expect(value.series.dau.data.daily.find(p => p.date === new Intl.DateTimeFormat('en-CA', {timeZone: 'America/New_York', year:'numeric', month:'2-digit', day:'2-digit'}).format(new Date(today)))?.value).toBe(1);
