    await database.query(`DELETE FROM agent_commands WHERE room_id=$1 AND reason<>'corner_objective'`, [corner]);
    readPullRequest.mockResolvedValueOnce(confirmDirty);
    await operations.processWebhook('pull_request', dirty);
